This C#/VB.NET code shows how to get information about all pixel types supported by the device.

            Public Shared Sub GetPixelTypesInfo()
                Using deviceManager As New Vintasoft.Twain.DeviceManager()
                    ' open the device manager
                    deviceManager.Open()

                    ' get reference to the default device
                    Dim device As Vintasoft.Twain.Device = deviceManager.DefaultDevice

                    ' open the device
                    device.Open()

                    ' get reference to object that manipulates IPixelType capability
                    Dim pixelTypeCap As Vintasoft.Twain.DeviceCapability = device.Capabilities.Find(Vintasoft.Twain.DeviceCapabilityId.IPixelType)
                    ' if IPixelType capability supported
                    If pixelTypeCap IsNot Nothing Then
                        ' get information about current, default and supported values of capability
                        Dim capValue As Vintasoft.Twain.TwainValueContainerBase = pixelTypeCap.GetValue()

                        Select Case capValue.ContainerType
                            Case Vintasoft.Twain.TwainValueContainerType.[Enum]
                                Dim capValueAsEnum As Vintasoft.Twain.TwainEnumValueContainer = DirectCast(capValue, Vintasoft.Twain.TwainEnumValueContainer)
                                Dim enumValues As System.Array = capValueAsEnum.EnumValues

                                ' output the capability values in human readable format
                                System.Console.WriteLine(String.Format("Current pixel type: {0}", enumValues.GetValue(capValueAsEnum.ValueIndex)))
                                System.Console.WriteLine(String.Format("Default pixel type: {0}", enumValues.GetValue(capValueAsEnum.DefaultValueIndex)))
                                System.Console.Write("Supported pixel types:")
                                For i As Integer = 0 To enumValues.Length - 1
                                    System.Console.Write(String.Format(" {0}", enumValues.GetValue(i)))
                                Next
                                Exit Select
                        End Select

                        System.Console.WriteLine()
                    End If

                    ' close the device
                    device.Close()

                    ' close the device manager
                    deviceManager.Close()
                End Using
            End Sub


            public static void GetPixelTypesInfo()
            {
                using (Vintasoft.Twain.DeviceManager deviceManager = new Vintasoft.Twain.DeviceManager())
                {
                    // open the device manager
                    deviceManager.Open();

                    // get reference to the default device
                    Vintasoft.Twain.Device device = deviceManager.DefaultDevice;

                    // open the device
                    device.Open();

                    // get reference to object that manipulates IPixelType capability
                    Vintasoft.Twain.DeviceCapability pixelTypeCap = device.Capabilities.Find(Vintasoft.Twain.DeviceCapabilityId.IPixelType);
                    // if IPixelType capability supported
                    if (pixelTypeCap != null)
                    {
                        // get information about current, default and supported values of capability
                        Vintasoft.Twain.TwainValueContainerBase capValue = pixelTypeCap.GetValue();

                        switch (capValue.ContainerType)
                        {
                            case Vintasoft.Twain.TwainValueContainerType.Enum:
                                Vintasoft.Twain.TwainEnumValueContainer capValueAsEnum = (Vintasoft.Twain.TwainEnumValueContainer)capValue;
                                System.Array enumValues = capValueAsEnum.EnumValues;

                                // output the capability values in human readable format
                                System.Console.WriteLine(string.Format("Current pixel type: {0}", enumValues.GetValue(capValueAsEnum.ValueIndex)));
                                System.Console.WriteLine(string.Format("Default pixel type: {0}", enumValues.GetValue(capValueAsEnum.DefaultValueIndex)));
                                System.Console.Write("Supported pixel types:");
                                for (int i = 0; i < enumValues.Length; i++)
                                    System.Console.Write(string.Format(" {0}", enumValues.GetValue(i)));
                                break;
                        }

                        System.Console.WriteLine();
                    }

                    // close the device
                    device.Close();

                    // close the device manager
                    deviceManager.Close();
                }
            }

This C#/VB.NET code shows how to detect when paper is jammed.

            ''' <summary>
            ''' Detects the paper jamm.
            ''' </summary>
            Public Sub DetectPaperJam(device As Vintasoft.Twain.Device)
                ' disable device UI
                device.ShowUI = False
                ' disable device when images are acquired
                device.DisableAfterAcquire = True

                ' open the device
                device.Open()

                ' set device settings
                device.PixelType = Vintasoft.Twain.PixelType.RGB
                device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches
                device.Resolution = New Vintasoft.Twain.Resolution(300.0F, 300.0F)

                Try
                    ' get events supported by device
                    Dim supportedDeviceEvents As Vintasoft.Twain.DeviceEventId() = device.GetSupportedAsyncEvents()
                    ' for each supported event
                    For i As Integer = 0 To supportedDeviceEvents.Length - 1
                        ' if device can report when paper is jammed
                        If supportedDeviceEvents(i) = Vintasoft.Twain.DeviceEventId.PaperJam Then
                            ' specify that device must report when paper is jammed
                            device.AsyncEvents = New Vintasoft.Twain.DeviceEventId() {Vintasoft.Twain.DeviceEventId.PaperJam}

                            ' subscribe to the device event
                            AddHandler device.AsyncEvent, New System.EventHandler(Of Vintasoft.Twain.DeviceAsyncEventArgs)(AddressOf device_DeviceEvent)

                            Exit For
                        End If
                    Next
                Catch ex As System.Exception
                    System.Console.WriteLine(ex.ToString())
                End Try

                ' subscribe to the Device.ImageAcquired, Device.ScanCompleted, ... events
                '...

                ' acquire images from device
                device.Acquire()
            End Sub

            ''' <summary>
            ''' Occurred the device event.
            ''' </summary>
            Private Sub device_DeviceEvent(sender As Object, e As Vintasoft.Twain.DeviceAsyncEventArgs)
                System.Console.WriteLine("Paper is jammed.")
            End Sub


            /// <summary>
            /// Detects the paper jamm.
            /// </summary>
            public void DetectPaperJam(Vintasoft.Twain.Device device)
            {
                // disable device UI
                device.ShowUI = false;
                // disable device when images are acquired
                device.DisableAfterAcquire = true;

                // open the device
                device.Open();

                // set device settings
                device.PixelType = Vintasoft.Twain.PixelType.RGB;
                device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches;
                device.Resolution = new Vintasoft.Twain.Resolution(300f, 300f);

                try
                {
                    // get events supported by device
                    Vintasoft.Twain.DeviceEventId[] supportedDeviceEvents = device.GetSupportedAsyncEvents();
                    // for each supported event
                    for (int i = 0; i < supportedDeviceEvents.Length; i++)
                    {
                        // if device can report when paper is jammed
                        if (supportedDeviceEvents[i] == Vintasoft.Twain.DeviceEventId.PaperJam)
                        {
                            // specify that device must report when paper is jammed
                            device.AsyncEvents = new Vintasoft.Twain.DeviceEventId[] { Vintasoft.Twain.DeviceEventId.PaperJam };

                            // subscribe to the device event
                            device.AsyncEvent += new System.EventHandler<Vintasoft.Twain.DeviceAsyncEventArgs>(device_DeviceEvent);

                            break;
                        }
                    }
                }
                catch (System.Exception ex)
                {
                    System.Console.WriteLine(ex.ToString());
                }

                // subscribe to the Device.ImageAcquired, Device.ScanCompleted, ... events
                //...

                // acquire images from device
                device.Acquire();
            }

            /// <summary>
            /// Occurred the device event.
            /// </summary>
            private void device_DeviceEvent(object sender, Vintasoft.Twain.DeviceAsyncEventArgs e)
            {
                System.Console.WriteLine("Paper is jammed.");
            }

This C#/VB.NET code shows how to asynchronously acquire images from the device.

            Imports Vintasoft.Twain

            Partial Public Class ScanAsynchronouslyDemoForm
                Inherits Form

            #Region "Fields"

                ''' <summary>
                ''' TWAIN device manager.
                ''' </summary>
                Private _deviceManager As Vintasoft.Twain.DeviceManager

            #End Region



            #Region "Constructors"

                Public Sub New()
                    InitializeComponent()

                    ' create and open device manager
                    _deviceManager = New Vintasoft.Twain.DeviceManager(Me, Me.Handle)
                    _deviceManager.Open()
                End Sub

            #End Region



            #Region "Methods"

                ''' <summary>
                ''' Starts the image acquisition from scanner.
                ''' </summary>
                Private Sub startImageAcquisitionButton_Click(ByVal sender As Object, ByVal e As EventArgs)
                    Dim device As Vintasoft.Twain.Device = Nothing
                    Try
                        ' select the default device
                        _deviceManager.ShowDefaultDeviceSelectionDialog()

                        ' get reference to the default device
                        device = _deviceManager.DefaultDevice
                        ' if device is not found
                        If device Is Nothing Then
                            Exit Sub
                        End If

                        ' subscribe to the device events
                        SubscribeToDeviceEvents(device)

                        ' set Memory transfer mode
                        device.TransferMode = Vintasoft.Twain.TransferMode.Memory
                        ' enable UI
                        device.ShowUI = True

                        ' open the device
                        device.Open()
                        ' specify that black-white images must be acquired
                        device.PixelType = Vintasoft.Twain.PixelType.BW
                        ' specify the threshold for acquired images
                        device.Threshold = 128
                        ' set the inches as unit of measure
                        device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches
                        device.Resolution = New Vintasoft.Twain.Resolution(300.0F, 300.0F)

                        ' acquire images asynchronously
                        device.Acquire()
                    Catch ex As Vintasoft.Twain.TwainException
                        ' if device is found
                        If device IsNot Nothing Then
                            ' if device is opened
                            If device.State >= Vintasoft.Twain.DeviceState.Opened Then
                                ' close the device
                                device.Close()
                            End If

                            ' unsubscribe from device events
                            UnsubscribeFromDeviceEvents(device)
                        End If

                        MsgBox(ex.Message)
                    End Try
                End Sub

                ''' <summary>
                ''' Image acquisition is in progress.
                ''' </summary>
                Private Sub device_ImageAcquiringProgress(ByVal sender As Object, ByVal e As Vintasoft.Twain.ImageAcquiringProgressEventArgs)
                    ' update progress bar
                    progressBar1.Value = e.Progress
                End Sub

                ''' <summary>
                ''' Image is acquired.
                ''' </summary>
                Private Sub device_ImageAcquired(ByVal sender As Object, ByVal e As Vintasoft.Twain.ImageAcquiredEventArgs)
                    ' dispose image stored in the picture box
                    If pictureBox1.Image IsNot Nothing Then
                        pictureBox1.Image.Dispose()
                        pictureBox1.Image = Nothing
                    End If

                    ' show acquired image in the picture box
                    pictureBox1.Image = e.Image.GetAsBitmap(True)

                    ' add the acquired image to a TIFF file
                    e.Image.Save(IO.Path.Combine(IO.Directory.GetCurrentDirectory(), "multipage.tif"))

                    ' dispose the acquired image
                    e.Image.Dispose()
                End Sub

                ''' <summary>
                ''' Scan is completed.
                ''' </summary>
                Private Sub device_ScanCompleted(ByVal sender As Object, ByVal e As EventArgs)
                    MessageBox.Show("Scan is competed.")
                End Sub

                ''' <summary>
                ''' Scan is canceled.
                ''' </summary>
                Private Sub device_ScanCanceled(ByVal sender As Object, ByVal e As EventArgs)
                    MessageBox.Show("Scan is canceled.")
                End Sub

                ''' <summary>
                ''' Scan is failed.
                ''' </summary>
                Private Sub device_ScanFailed(ByVal sender As Object, ByVal e As Vintasoft.Twain.ScanFailedEventArgs)
                    MessageBox.Show(String.Format("Scan is failed: {0}", e.ErrorString))
                End Sub

                ''' <summary>
                ''' User interface of device is closed.
                ''' </summary>
                Private Sub device_UserInterfaceClosed(ByVal sender As Object, ByVal e As EventArgs)
                    MessageBox.Show("User Interface is closed.")
                End Sub

                ''' <summary>
                ''' Scan is finished.
                ''' </summary>
                Private Sub device_ScanFinished(ByVal sender As Object, ByVal e As EventArgs)
                    Dim device1 As Vintasoft.Twain.Device = DirectCast(sender, Vintasoft.Twain.Device)

                    ' unsubscribe from device events
                    UnsubscribeFromDeviceEvents(device1)

                    ' if device is not closed
                    If device1.State <> Vintasoft.Twain.DeviceState.Closed Then
                        ' close the device
                        device1.Close()
                    End If

                    MessageBox.Show("Scan is finished.")
                End Sub

                ''' <summary>
                ''' Subscribes to the device events.
                ''' </summary>
                Private Sub SubscribeToDeviceEvents(ByVal device As Vintasoft.Twain.Device)
                    AddHandler device.ImageAcquiringProgress, New EventHandler(Of Vintasoft.Twain.ImageAcquiringProgressEventArgs)(AddressOf device_ImageAcquiringProgress)
                    AddHandler device.ImageAcquired, New EventHandler(Of Vintasoft.Twain.ImageAcquiredEventArgs)(AddressOf device_ImageAcquired)
                    AddHandler device.ScanCompleted, New EventHandler(AddressOf device_ScanCompleted)
                    AddHandler device.ScanCanceled, New EventHandler(AddressOf device_ScanCanceled)
                    AddHandler device.ScanFailed, New EventHandler(Of Vintasoft.Twain.ScanFailedEventArgs)(AddressOf device_ScanFailed)
                    AddHandler device.UserInterfaceClosed, New EventHandler(AddressOf device_UserInterfaceClosed)
                    AddHandler device.ScanFinished, New EventHandler(AddressOf device_ScanFinished)
                End Sub

                ''' <summary>
                ''' Unsubscribes from the device events.
                ''' </summary>
                Private Sub UnsubscribeFromDeviceEvents(ByVal device As Vintasoft.Twain.Device)
                    RemoveHandler device.ImageAcquiringProgress, New EventHandler(Of Vintasoft.Twain.ImageAcquiringProgressEventArgs)(AddressOf device_ImageAcquiringProgress)
                    RemoveHandler device.ImageAcquired, New EventHandler(Of Vintasoft.Twain.ImageAcquiredEventArgs)(AddressOf device_ImageAcquired)
                    RemoveHandler device.ScanCompleted, New EventHandler(AddressOf device_ScanCompleted)
                    RemoveHandler device.ScanCanceled, New EventHandler(AddressOf device_ScanCanceled)
                    RemoveHandler device.ScanFailed, New EventHandler(Of Vintasoft.Twain.ScanFailedEventArgs)(AddressOf device_ScanFailed)
                    RemoveHandler device.UserInterfaceClosed, New EventHandler(AddressOf device_UserInterfaceClosed)
                    RemoveHandler device.ScanFinished, New EventHandler(AddressOf device_ScanFinished)
                End Sub

