            namespace TwainExamples_CSharp
            {
                public partial class ScanAsynchronouslyDemoForm : System.Windows.Forms.Form
                {

                    #region Fields

                    /// <summary>
                    /// TWAIN device manager.
                    /// </summary>
                    Vintasoft.Twain.DeviceManager _deviceManager;

                    #endregion



                    #region Constructors

                    public ScanAsynchronouslyDemoForm()
                    {
                        InitializeComponent();

                        // create and open device manager
                        _deviceManager = new Vintasoft.Twain.DeviceManager(this, this.Handle);
                        _deviceManager.Open();
                    }

                    #endregion



                    #region Methods

                    /// <summary>
                    /// Starts the image acquisition from scanner.
                    /// </summary>
                    private void startImageAcquisitionButton_Click(object sender, System.EventArgs e)
                    {
                        Vintasoft.Twain.Device device = null;
                        try
                        {
                            // select the default device
                            _deviceManager.ShowDefaultDeviceSelectionDialog();

                            // get reference to the default device
                            device = _deviceManager.DefaultDevice;
                            // if device is not found
                            if (device == null)
                                return;

                            // subscribe to the device events
                            SubscribeToDeviceEvents(device);

                            // set Memory transfer mode
                            device.TransferMode = Vintasoft.Twain.TransferMode.Memory;
                            // enable UI
                            device.ShowUI = true;

                            // open the device
                            device.Open();
                            // specify that black-white images must be acquired
                            device.PixelType = Vintasoft.Twain.PixelType.BW;
                            // specify the threshold for acquired images
                            device.Threshold = 128;
                            // set the inches as unit of measure
                            device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches;
                            device.Resolution = new Vintasoft.Twain.Resolution(300f, 300f);

                            // acquire images asynchronously
                            device.Acquire();
                        }
                        catch (Vintasoft.Twain.TwainException ex)
                        {
                            // if device is found
                            if (device != null)
                            {
                                // if device is opened
                                if (device.State >= Vintasoft.Twain.DeviceState.Opened)
                                    // close the device
                                    device.Close();

                                // unsubscribe from device events
                                UnsubscribeFromDeviceEvents(device);
                            }

                            System.Windows.Forms.MessageBox.Show(ex.Message);
                        }
                    }

                    /// <summary>
                    /// Image acquisition is in progress.
                    /// </summary>
                    private void device_ImageAcquiringProgress(
                        object sender,
                        Vintasoft.Twain.ImageAcquiringProgressEventArgs e)
                    {
                        // update progress bar
                        progressBar1.Value = e.Progress;
                    }

                    /// <summary>
                    /// Image is acquired.
                    /// </summary>
                    private void device_ImageAcquired(object sender, Vintasoft.Twain.ImageAcquiredEventArgs e)
                    {
                        // dispose image stored in the picture box
                        if (pictureBox1.Image != null)
                        {
                            pictureBox1.Image.Dispose();
                            pictureBox1.Image = null;
                        }

                        // show acquired image in the picture box
                        pictureBox1.Image = e.Image.GetAsBitmap(true);

                        // add the acquired image to a TIFF file
                        e.Image.Save(System.IO.Path.Combine(System.IO.Directory.GetCurrentDirectory(), "multipage.tif"));

                        // dispose the acquired image
                        e.Image.Dispose();
                    }

                    /// <summary>
                    /// Scan is completed.
                    /// </summary>
                    private void device_ScanCompleted(object sender, System.EventArgs e)
                    {
                        System.Windows.Forms.MessageBox.Show("Scan is competed.");
                    }

                    /// <summary>
                    /// Scan is canceled.
                    /// </summary>
                    private void device_ScanCanceled(object sender, System.EventArgs e)
                    {
                        System.Windows.Forms.MessageBox.Show("Scan is canceled.");
                    }

                    /// <summary>
                    /// Scan is failed.
                    /// </summary>
                    private void device_ScanFailed(object sender, Vintasoft.Twain.ScanFailedEventArgs e)
                    {
                        System.Windows.Forms.MessageBox.Show(string.Format("Scan is failed: {0}", e.ErrorString));
                    }

                    /// <summary>
                    /// User interface of device is closed.
                    /// </summary>
                    private void device_UserInterfaceClosed(object sender, System.EventArgs e)
                    {
                        System.Windows.Forms.MessageBox.Show("User Interface is closed.");
                    }

                    /// <summary>
                    /// Scan is finished.
                    /// </summary>
                    private void device_ScanFinished(object sender, System.EventArgs e)
                    {
                        Vintasoft.Twain.Device device = (Vintasoft.Twain.Device)sender;

                        // unsubscribe from device events
                        UnsubscribeFromDeviceEvents(device);

                        // if device is not closed
                        if (device.State != Vintasoft.Twain.DeviceState.Closed)
                            // close the device
                            device.Close();

                        System.Windows.Forms.MessageBox.Show("Scan is finished.");
                    }

                    /// <summary>
                    /// Subscribes to the device events.
                    /// </summary>
                    private void SubscribeToDeviceEvents(Vintasoft.Twain.Device device)
                    {
                        device.ImageAcquiringProgress += new System.EventHandler<Vintasoft.Twain.ImageAcquiringProgressEventArgs>(device_ImageAcquiringProgress);
                        device.ImageAcquired += new System.EventHandler<Vintasoft.Twain.ImageAcquiredEventArgs>(device_ImageAcquired);
                        device.ScanCompleted += new System.EventHandler(device_ScanCompleted);
                        device.ScanCanceled += new System.EventHandler(device_ScanCanceled);
                        device.ScanFailed += new System.EventHandler<Vintasoft.Twain.ScanFailedEventArgs>(device_ScanFailed);
                        device.UserInterfaceClosed += new System.EventHandler(device_UserInterfaceClosed);
                        device.ScanFinished += new System.EventHandler(device_ScanFinished);
                    }

                    /// <summary>
                    /// Unsubscribes from the device events.
                    /// </summary>
                    private void UnsubscribeFromDeviceEvents(Vintasoft.Twain.Device device)
                    {
                        device.ImageAcquiringProgress -= new System.EventHandler<Vintasoft.Twain.ImageAcquiringProgressEventArgs>(device_ImageAcquiringProgress);
                        device.ImageAcquired -= new System.EventHandler<Vintasoft.Twain.ImageAcquiredEventArgs>(device_ImageAcquired);
                        device.ScanCompleted -= new System.EventHandler(device_ScanCompleted);
                        device.ScanCanceled -= new System.EventHandler(device_ScanCanceled);
                        device.ScanFailed -= new System.EventHandler<Vintasoft.Twain.ScanFailedEventArgs>(device_ScanFailed);
                        device.UserInterfaceClosed -= new System.EventHandler(device_UserInterfaceClosed);
                        device.ScanFinished -= new System.EventHandler(device_ScanFinished);
                    }

                    #endregion

                }
            }

This C#/VB.NET code shows how to synchronously acquire images from the device.

            Public Shared Sub AcquireImageModal()
                Try
                    ' create the device manager
                    Using deviceManager As New Vintasoft.Twain.DeviceManager()
                        ' open the device manager
                        deviceManager.Open()

                        ' get reference to the default device
                        Dim device As Vintasoft.Twain.Device = deviceManager.DefaultDevice

                        device.ShowUI = False
                        device.DisableAfterAcquire = True

                        ' open the device
                        device.Open()

                        ' set acquisition parameters
                        device.TransferMode = Vintasoft.Twain.TransferMode.Memory
                        device.PixelType = Vintasoft.Twain.PixelType.BW

                        ' create directory for TIFF file
                        Dim directoryForImages As String = System.IO.Path.GetDirectoryName(System.IO.Directory.GetCurrentDirectory())
                        directoryForImages = System.IO.Path.Combine(directoryForImages, "Images")
                        If Not System.IO.Directory.Exists(directoryForImages) Then
                            System.IO.Directory.CreateDirectory(directoryForImages)
                        End If

                        Dim multipageTiffFilename As String = System.IO.Path.Combine(directoryForImages, "multipage.tif")

                        ' acquire image(s) from the device
                        Dim acquireModalState As Vintasoft.Twain.AcquireModalState = Vintasoft.Twain.AcquireModalState.None
                        Dim imageIndex As Integer = 0
                        Do
                            acquireModalState = device.AcquireModal()
                            Select Case acquireModalState
                                Case Vintasoft.Twain.AcquireModalState.ImageAcquiring
                                    ' output current state
                                    System.Console.Write(String.Format("Image is acquiring ", System.Math.Max(System.Threading.Interlocked.Increment(imageIndex), imageIndex - 1)))
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ImageAcquiringProgress
                                    ' output current state
                                    System.Console.Write(String.Format("{0}% ", device.ImageAcquiringProgressValue))
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ImageAcquired
                                    ' save the acquired image to a file
                                    device.AcquiredImage.Save(multipageTiffFilename)
                                    ' dispose the acquired image
                                    device.AcquiredImage.Dispose()
                                    ' output current state
                                    System.Console.WriteLine(String.Format("Image{0} is saved.", System.Math.Max(System.Threading.Interlocked.Increment(imageIndex), imageIndex - 1)))
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanCompleted
                                    ' output current state
                                    System.Console.WriteLine("Scan is completed.")
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanCanceled
                                    ' output current state
                                    System.Console.WriteLine("Scan is canceled.")
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanFailed
                                    ' output current state
                                    System.Console.WriteLine(String.Format("Scan is failed: {0}", device.ErrorString))
                                    Exit Select
                            End Select
                        Loop While acquireModalState <> Vintasoft.Twain.AcquireModalState.None

                        ' close the device
                        device.Close()

                        ' close the device manager
                        deviceManager.Close()
                    End Using
                Catch ex As Vintasoft.Twain.TwainException
                    System.Console.WriteLine("Error: " + ex.Message)
                End Try
            End Sub


            public static void AcquireImageModal()
            {
                try
                {
                    // create the device manager
                    using (Vintasoft.Twain.DeviceManager deviceManager = new Vintasoft.Twain.DeviceManager())
                    {
                        // open the device manager
                        deviceManager.Open();

                        // get reference to the default device
                        Vintasoft.Twain.Device device = deviceManager.DefaultDevice;

                        device.ShowUI = false;
                        device.DisableAfterAcquire = true;

                        // open the device
                        device.Open();

                        // set acquisition parameters
                        device.TransferMode = Vintasoft.Twain.TransferMode.Memory;
                        device.PixelType = Vintasoft.Twain.PixelType.BW;

                        // create directory for TIFF file
                        string directoryForImages = System.IO.Path.GetDirectoryName(System.IO.Directory.GetCurrentDirectory());
                        directoryForImages = System.IO.Path.Combine(directoryForImages, "Images");
                        if (!System.IO.Directory.Exists(directoryForImages))
                            System.IO.Directory.CreateDirectory(directoryForImages);

                        string multipageTiffFilename = System.IO.Path.Combine(directoryForImages, "multipage.tif");

                        // acquire image(s) from the device
                        Vintasoft.Twain.AcquireModalState acquireModalState = Vintasoft.Twain.AcquireModalState.None;
                        int imageIndex = 0;
                        do
                        {
                            acquireModalState = device.AcquireModal();
                            switch (acquireModalState)
                            {
                                case Vintasoft.Twain.AcquireModalState.ImageAcquiring:
                                    // output current state
                                    System.Console.Write(string.Format("Image is acquiring ", imageIndex++));
                                    break;

                                case Vintasoft.Twain.AcquireModalState.ImageAcquiringProgress:
                                    // output current state
                                    System.Console.Write(string.Format("{0}% ", device.ImageAcquiringProgressValue));
                                    break;

                                case Vintasoft.Twain.AcquireModalState.ImageAcquired:
                                    // save the acquired image to a file
                                    device.AcquiredImage.Save(multipageTiffFilename);
                                    // dispose the acquired image
                                    device.AcquiredImage.Dispose();
                                    // output current state
                                    System.Console.WriteLine(string.Format("Image{0} is saved.", imageIndex++));
                                    break;

                                case Vintasoft.Twain.AcquireModalState.ScanCompleted:
                                    // output current state
                                    System.Console.WriteLine("Scan is completed.");
                                    break;

                                case Vintasoft.Twain.AcquireModalState.ScanCanceled:
                                    // output current state
                                    System.Console.WriteLine("Scan is canceled.");
                                    break;

                                case Vintasoft.Twain.AcquireModalState.ScanFailed:
                                    // output current state
                                    System.Console.WriteLine(string.Format("Scan is failed: {0}", device.ErrorString));
                                    break;
                            }
                        }
                        while (acquireModalState != Vintasoft.Twain.AcquireModalState.None);

                        // close the device
                        device.Close();

                        // close the device manager
                        deviceManager.Close();
                    }
                }
                catch (Vintasoft.Twain.TwainException ex)
                {
                    System.Console.WriteLine("Error: " + ex.Message);
                }
            }

This C#/VB.NET code shows how to cancel current asynchronous image transfer.

            Class SyncScan_Cancel

            	''' <summary>
            	''' This method scans one image and cancels image scan.
            	''' </summary>
            	Public Shared Sub ScanOneImageAndCancelScan()
            		Dim isScanCanceled As Boolean = False

            		' create the device manager
            		Using deviceManager As New Vintasoft.Twain.DeviceManager()
            			deviceManager.IsTwain2Compatible = True
            			' open the device manager
            			deviceManager.Open()

            			' get the device
            			Dim deviceName As String = "KODAK Scanner: i5000"
            			Dim device As Vintasoft.Twain.Device = deviceManager.Devices.Find(deviceName)
            			If device Is Nothing Then
            				Throw New ApplicationException(String.Format("Device '{0}' is not found.", deviceName))
            			End If

            			' disable device UI
            			device.ShowUI = False
            			' specify that device must be closed after scan
            			device.DisableAfterAcquire = True

            			' open the device
            			device.Open()
            			' specify that 2 images must be acquired from scanner
            			device.XferCount = 2

            			' run asynchronous image acquisition
            			Dim acquireModalState1 As Vintasoft.Twain.AcquireModalState = Vintasoft.Twain.AcquireModalState.None
            			Do
            				acquireModalState1 = device.AcquireModal()
            				Select Case acquireModalState1
            					Case Vintasoft.Twain.AcquireModalState.ImageAcquired
            						Console.WriteLine("Image is acquired.")
            						If device.AcquiredImage IsNot Nothing Then
            							device.AcquiredImage.Dispose()
            						End If

            						' cancel image scan
            						device.CancelTransfer()
            						Exit Select

            					Case Vintasoft.Twain.AcquireModalState.ScanCompleted
            						Console.WriteLine("Scan is completed.")
            						Exit Select

            					Case Vintasoft.Twain.AcquireModalState.ScanCanceled
            						isScanCanceled = True
            						Console.WriteLine("Scan is canceled.")
            						Exit Select

            					Case Vintasoft.Twain.AcquireModalState.ScanFailed
            						Console.WriteLine(String.Format("Scan is failed: {0}.", device.ErrorString))
            						Exit Select
            				End Select
            			Loop While acquireModalState1 <> Vintasoft.Twain.AcquireModalState.None

            			If Not isScanCanceled Then
            				Throw New ApplicationException("Scan is NOT canceled.")
            			End If

            			' close the device
            			device.Close()
            		End Using
            	End Sub

            End Class


            namespace TwainExamples_CSharp
            {
                class SyncScan_Cancel
                {

                    /// <summary>
                    /// This method scans one image and cancels image scan.
                    /// </summary>
                    public static void ScanOneImageAndCancelScan()
                    {
                        bool isScanCanceled = false;

                        // create the device manager
                        using (Vintasoft.Twain.DeviceManager deviceManager = new Vintasoft.Twain.DeviceManager())
                        {
                            deviceManager.IsTwain2Compatible = true;
                            // open the device manager
                            deviceManager.Open();

                            // get the device
                            string deviceName = "KODAK Scanner: i5000";
                            Vintasoft.Twain.Device device = deviceManager.Devices.Find(deviceName);
                            if (device == null)
                                throw new System.ApplicationException(string.Format("Device '{0}' is not found.", deviceName));

                            // disable device UI
                            device.ShowUI = false;
                            // specify that device must be closed after scan
                            device.DisableAfterAcquire = true;

                            // open the device
                            device.Open();
                            // specify that 2 images must be acquired from scanner
                            device.XferCount = 2;

                            // run asynchronous image acquisition
                            Vintasoft.Twain.AcquireModalState acquireModalState = Vintasoft.Twain.AcquireModalState.None;
                            do
                            {
                                acquireModalState = device.AcquireModal();
                                switch (acquireModalState)
                                {
                                    case Vintasoft.Twain.AcquireModalState.ImageAcquired:
                                        System.Console.WriteLine("Image is acquired.");
                                        if (device.AcquiredImage != null)
                                            device.AcquiredImage.Dispose();

                                        // cancel image scan
                                        device.CancelTransfer();
                                        break;

                                    case Vintasoft.Twain.AcquireModalState.ScanCompleted:
                                        System.Console.WriteLine("Scan is completed.");
                                        break;

                                    case Vintasoft.Twain.AcquireModalState.ScanCanceled:
                                        isScanCanceled = true;
                                        System.Console.WriteLine("Scan is canceled.");
                                        break;

                                    case Vintasoft.Twain.AcquireModalState.ScanFailed:
                                        System.Console.WriteLine(string.Format("Scan is failed: {0}.", device.ErrorString));
                                        break;
                                }
                            }
                            while (acquireModalState != Vintasoft.Twain.AcquireModalState.None);

                            if (!isScanCanceled)
                                throw new System.ApplicationException("Scan is NOT canceled.");

                            // close the device
                            device.Close();
                        }
                    }

                }
            }

This C#/VB.NET code shows how to pause the image acquisition from feeder
            (stop the feeder) and resume the image acquisition from feeder.

            Class SyncScan_StopFeeder

                ''' <summary>
                ''' This method scans the first image, stops the document feeder,
                ''' scans the second image.
                ''' </summary>
                Public Shared Sub ScanImage_StopFeeder_ScanImage()
                    Dim imageCount As Integer = 0

                    ' create the device manager
                    Using deviceManager As New Vintasoft.Twain.DeviceManager()
                        deviceManager.IsTwain2Compatible = True
                        ' open the device manager
                        deviceManager.Open()

                        ' get the device
                        Dim deviceName As String = "KODAK Scanner: i5000"
                        Dim device As Vintasoft.Twain.Device = deviceManager.Devices.Find(deviceName)
                        If device Is Nothing Then
                            Throw New ApplicationException(String.Format("Device '{0}' is not found.", deviceName))
                        End If

                        ' disable device UI
                        device.ShowUI = False
                        ' specify that device must be closed after scan
                        device.DisableAfterAcquire = True

                        ' open the device
                        device.Open()
                        ' specify that 2 images must be acquired from scanner
                        device.XferCount = 2

                        ' run synchronous image acquisition
                        Dim acquireModalState1 As Vintasoft.Twain.AcquireModalState = Vintasoft.Twain.AcquireModalState.None
                        Do
                            acquireModalState1 = device.AcquireModal()
                            Select Case acquireModalState1
                                Case Vintasoft.Twain.AcquireModalState.ImageAcquired
                                    Console.WriteLine("Image is acquired.")
                                    If device.AcquiredImage IsNot Nothing Then
                                        device.AcquiredImage.Dispose()
                                    End If

                                    imageCount += 1

                                    ' stop the feeder
                                    device.StopFeeder()
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanCompleted
                                    Console.WriteLine("Scan is completed.")
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanCanceled
                                    Console.WriteLine("Scan is canceled.")
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanFailed
                                    Console.WriteLine(String.Format("Scan is failed: {0}.", device.ErrorString))
                                    Exit Select
                            End Select
                        Loop While acquireModalState1 <> Vintasoft.Twain.AcquireModalState.None

                        If imageCount <> 1 Then
                            Throw New ApplicationException("Wrong acquired image count.")
                        End If

                        If device.State <> Vintasoft.Twain.DeviceState.TransferReady Then
                            Throw New ApplicationException("Feeder is NOT stopped.")
                        End If
                        Console.WriteLine("Feeder is stopped.")

                        ' continue asynchronous image acquisition
                        Do
                            acquireModalState1 = device.AcquireModal()
                            Select Case acquireModalState1
                                Case Vintasoft.Twain.AcquireModalState.ImageAcquired
                                    Console.WriteLine("Image is acquired.")

                                    If device.AcquiredImage IsNot Nothing Then
                                        device.AcquiredImage.Dispose()
                                    End If

                                    imageCount = imageCount + 1
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanCompleted
                                    Console.WriteLine("Scan is completed.")
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanCanceled
                                    Console.WriteLine("Scan is canceled.")
                                    Exit Select

                                Case Vintasoft.Twain.AcquireModalState.ScanFailed
                                    Console.WriteLine(String.Format("Scan is failed: {0}.", device.ErrorString))
                                    Exit Select
                            End Select
                        Loop While acquireModalState1 <> Vintasoft.Twain.AcquireModalState.None

                        If imageCount <> 2 Then
                            Throw New ApplicationException("Wrong acquired image count.")
                        End If

                        ' close the device
                        device.Close()
                    End Using
                End Sub

            End Class


