member.example:
This C#/VB.NET code shows how to use Dual Stream feature of Kodak scanner.

            Private Shared Sub AcquiredImagesWithDualStream()
                ' create the device manager
                Using deviceManager As New Vintasoft.Twain.DeviceManager()
                    ' open the device manager
                    deviceManager.Open()

                    ' get reference to Kodak scanner
                    Dim device As Vintasoft.Twain.Device = deviceManager.Devices.Find("KODAK Scanner: i1410/i1420/i1440")

                    ' disable UI
                    device.ShowUI = False

                    ' open device
                    device.Open()

                    ' set inches as units of measure
                    device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches
                    ' enable duplex
                    device.DocumentFeeder.DuplexEnabled = True

                    ' select color camera
                    device.Cameras.SetSelectedCamera("/Camera_Color_Both")
                    ' set resolution for color images
                    device.Resolution = New Vintasoft.Twain.Resolution(300, 300)
                    ' enable color camera
                    device.Cameras.EnableSelectedCamera()

                    ' select black-white camera
                    device.Cameras.SetSelectedCamera("/Camera_Bitonal_Both")
                    ' set resolution for black-white images
                    device.Resolution = New Vintasoft.Twain.Resolution(200, 200)
                    ' enable black-white camera
                    device.Cameras.EnableSelectedCamera()


                    ' modally acquire images from the scanner
                    Dim acquireModalState As Vintasoft.Twain.AcquireModalState = Vintasoft.Twain.AcquireModalState.None
                    Dim acquiredImageInfo As Vintasoft.Twain.ImageInfo
                    Do
                        ' acquire image from scanner
                        acquireModalState = device.AcquireModal()

                        ' write information about acquired image
                        If acquireModalState = Vintasoft.Twain.AcquireModalState.ImageAcquired Then
                            ' get info about acquired image
                            acquiredImageInfo = device.AcquiredImage.ImageInfo
                            ' output info about acquired image
                            System.Console.WriteLine(acquiredImageInfo.PixelType.ToString() & " " & acquiredImageInfo.Resolution.ToString())

                            ' dispose the acquired image
                            device.AcquiredImage.Dispose()
                        End If
                    Loop While acquireModalState <> Vintasoft.Twain.AcquireModalState.None

                    ' close the device
                    device.Close()

                    ' close TWAIN device manager
                    deviceManager.Close()
                End Using
            End Sub


            private static void AcquiredImagesWithDualStream()
            {
                // create the device manager
                using (Vintasoft.Twain.DeviceManager deviceManager = new Vintasoft.Twain.DeviceManager())
                {
                    // open the device manager
                    deviceManager.Open();

                    // get reference to Kodak scanner
                    Vintasoft.Twain.Device device = deviceManager.Devices.Find("KODAK Scanner: i1410/i1420/i1440");

                    // disable UI
                    device.ShowUI = false;

                    // open device
                    device.Open();

                    // set inches as units of measure
                    device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches;
                    // enable duplex
                    device.DocumentFeeder.DuplexEnabled = true;

                    // select color camera
                    device.Cameras.SetSelectedCamera("/Camera_Color_Both");
                    // set resolution for color images
                    device.Resolution = new Vintasoft.Twain.Resolution(300, 300);
                    // enable color camera
                    device.Cameras.EnableSelectedCamera();

                    // select black-white camera
                    device.Cameras.SetSelectedCamera("/Camera_Bitonal_Both");
                    // set resolution for black-white images
                    device.Resolution = new Vintasoft.Twain.Resolution(200, 200);
                    // enable black-white camera
                    device.Cameras.EnableSelectedCamera();


                    // modally acquire images from the scanner
                    Vintasoft.Twain.AcquireModalState acquireModalState = Vintasoft.Twain.AcquireModalState.None;
                    Vintasoft.Twain.ImageInfo acquiredImageInfo;
                    do
                    {
                        // acquire image from scanner
                        acquireModalState = device.AcquireModal();

                        // write information about acquired image
                        if (acquireModalState == Vintasoft.Twain.AcquireModalState.ImageAcquired)
                        {
                            // get info about acquired image
                            acquiredImageInfo = device.AcquiredImage.ImageInfo;
                            // output info about acquired image
                            System.Console.WriteLine(acquiredImageInfo.PixelType.ToString() + " " + acquiredImageInfo.Resolution.ToString());

                            // dispose the acquired image
                            device.AcquiredImage.Dispose();
                        }
                    }
                    while (acquireModalState != Vintasoft.Twain.AcquireModalState.None);

                    // close the device
                    device.Close();

                    // close TWAIN device manager
                    deviceManager.Close();
                }
            }

This C#/VB.NET code shows how to get information about all pixel types supported by the device.

            Private Shared Sub GetPixelTypesInfo()
                Using deviceManager As New Vintasoft.Twain.DeviceManager()
                    ' open the device manager
                    deviceManager.Open()

                    ' get reference to the deafult device
                    Dim device As Vintasoft.Twain.Device = deviceManager.DefaultDevice

                    ' open the device
                    device.Open()

                    ' get reference to object that manipulates IPixelType capability
                    Dim pixelTypeCap As Vintasoft.Twain.DeviceCapability = device.Capabilities.Find(Vintasoft.Twain.DeviceCapabilityId.IPixelType)
                    ' if IPixelType capability supported
                    If pixelTypeCap IsNot Nothing Then
                        ' get information about current, default and supported values of capability
                        Dim capValue As Vintasoft.Twain.TwainValueContainerBase = pixelTypeCap.GetValue()

                        Select Case capValue.ContainerType
                            Case Vintasoft.Twain.TwainValueContainerType.[Enum]
                                Dim capValueAsEnum As Vintasoft.Twain.TwainEnumValueContainer = DirectCast(capValue, Vintasoft.Twain.TwainEnumValueContainer)
                                Dim enumValues As System.Array = capValueAsEnum.EnumValues

                                ' output the capability values in human readable format
                                System.Console.WriteLine(String.Format("Current pixel type: {0}", enumValues.GetValue(capValueAsEnum.ValueIndex)))
                                System.Console.WriteLine(String.Format("Default pixel type: {0}", enumValues.GetValue(capValueAsEnum.DefaultValueIndex)))
                                System.Console.Write("Supported pixel types:")
                                For i As Integer = 0 To enumValues.Length - 1
                                    System.Console.Write(String.Format(" {0}", enumValues.GetValue(i)))
                                Next
                                Exit Select
                        End Select

                        System.Console.WriteLine()
                    End If

                    ' close the device
                    device.Close()

                    ' close the device manager
                    deviceManager.Close()
                End Using
            End Sub


            private static void GetPixelTypesInfo()
            {
                using (Vintasoft.Twain.DeviceManager deviceManager = new Vintasoft.Twain.DeviceManager())
                {
                    // open the device manager
                    deviceManager.Open();

                    // get reference to the deafult device
                    Vintasoft.Twain.Device device = deviceManager.DefaultDevice;

                    // open the device
                    device.Open();

                    // get reference to object that manipulates IPixelType capability
                    Vintasoft.Twain.DeviceCapability pixelTypeCap = device.Capabilities.Find(Vintasoft.Twain.DeviceCapabilityId.IPixelType);
                    // if IPixelType capability supported
                    if (pixelTypeCap != null)
                    {
                        // get information about current, default and supported values of capability
                        Vintasoft.Twain.TwainValueContainerBase capValue = pixelTypeCap.GetValue();

                        switch (capValue.ContainerType)
                        {
                            case Vintasoft.Twain.TwainValueContainerType.Enum:
                                Vintasoft.Twain.TwainEnumValueContainer capValueAsEnum = (Vintasoft.Twain.TwainEnumValueContainer)capValue;
                                System.Array enumValues = capValueAsEnum.EnumValues;

                                // output the capability values in human readable format
                                System.Console.WriteLine(string.Format("Current pixel type: {0}", enumValues.GetValue(capValueAsEnum.ValueIndex)));
                                System.Console.WriteLine(string.Format("Default pixel type: {0}", enumValues.GetValue(capValueAsEnum.DefaultValueIndex)));
                                System.Console.Write("Supported pixel types:");
                                for (int i = 0; i < enumValues.Length; i++)
                                    System.Console.Write(string.Format(" {0}", enumValues.GetValue(i)));
                                break;
                        }

                        System.Console.WriteLine();
                    }

                    // close the device
                    device.Close();

                    // close the device manager
                    deviceManager.Close();
                }
            }

This C#/VB.NET code shows how to add the "custom" capability to the list of capabilities.

            ''' <summary>
            ''' Adds the "custom" capability to the device capability collection.
            ''' </summary>
            Public Shared Sub AddCustomDeviceCapability(device As Vintasoft.Twain.Device)
                ' open the device
                device.Open()

                Dim customCapId As System.UInt16 = 30000
                ' add the "custom" capability to the device capability collection
                device.Capabilities.Add(customCapId)

                ' get the "custom" capability
                Dim cap30000 As Vintasoft.Twain.DeviceCapability = device.Capabilities.Find(customCapId)
                Try
                    ' set the current value of "custom" capability to True
                    cap30000.SetValue(True)
                Catch ex As System.Exception
                    System.Console.WriteLine(String.Format("Error: {0}", ex.Message))
                End Try
            End Sub


            /// <summary>
            /// Adds the "custom" capability to the device capability collection.
            /// </summary>
            public static void AddCustomDeviceCapability(Vintasoft.Twain.Device device)
            {
                // open the device
                device.Open();

                System.UInt16 customCapId = 30000;
                // add the "custom" capability to the device capability collection
                device.Capabilities.Add(customCapId);

                // get the "custom" capability
                Vintasoft.Twain.DeviceCapability cap30000 = device.Capabilities.Find(customCapId);
                try
                {
                    // set the current value of "custom" capability to True
                    cap30000.SetValue(true);
                }
                catch (System.Exception ex)
                {
                    System.Console.WriteLine(string.Format("Error: {0}", ex.Message));
                }
            }

