                    device.Open();

                    // get reference to object that manipulates DuplexEnabled capability
                    Vintasoft.Twain.DeviceCapability duplexEnabledCap = device.Capabilities.Find(Vintasoft.Twain.DeviceCapabilityId.DuplexEnabled);
                    // if DuplexEnabled capability supported
                    if (duplexEnabledCap != null)
                    {
                        // set value of DuplexEnabled capability
                        duplexEnabledCap.SetValue(true);
                    }

                    // close the device
                    device.Close();

                    // close the device manager
                    deviceManager1.Close();
                }
            }

This C#/VB.NET code shows how to use document feeder of the device.

            ''' <summary>
            ''' Acquire images from the document feeder.
            ''' </summary>
            Public Sub AcquireImagesFromAdf(device As Vintasoft.Twain.Device)
                ' disable UI
                device.ShowUI = False

                ' open the device
                device.Open()
                ' specify that color images must be acquired
                device.PixelType = Vintasoft.Twain.PixelType.RGB
                ' set the inches as unit of measure
                device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches
                ' set the desired resolution of acquired images
                device.Resolution = New Vintasoft.Twain.Resolution(200.0F, 200.0F)

                ' if device has feeder
                If device.HasFeeder Then
                    ' enable feeder
                    device.DocumentFeeder.Enabled = True
                    ' specify that application want to acquire all pages from the feeder
                    device.XferCount = -1

                    ' if pages can be scanned in duplex mode
                    If device.DocumentFeeder.DuplexMode <> Vintasoft.Twain.DuplexMode.None Then
                        ' enable duplex scanning
                        device.DocumentFeeder.DuplexEnabled = True
                    End If

                    ' if feeder can detect paper
                    If device.DocumentFeeder.PaperDetectable Then
                        ' if feeder is loaded
                        If device.DocumentFeeder.Loaded Then
                            ' acquire images asynchronously
                            device.Acquire()
                        End If
                    Else
                        ' if feeder cannot detect paper
                        ' acquire images asynchronously
                        device.Acquire()
                    End If
                End If
            End Sub


            /// <summary>
            /// Acquire images from the document feeder.
            /// </summary>
            public void AcquireImagesFromAdf(Vintasoft.Twain.Device device)
            {
                // disable UI
                device.ShowUI = false;

                // open the device
                device.Open();
                // specify that color images must be acquired
                device.PixelType = Vintasoft.Twain.PixelType.RGB;
                // set the inches as unit of measure
                device.UnitOfMeasure = Vintasoft.Twain.UnitOfMeasure.Inches;
                // set the desired resolution of acquired images
                device.Resolution = new Vintasoft.Twain.Resolution(200f, 200f);

                // if device has feeder
                if (device.HasFeeder)
                {
                    // enable feeder
                    device.DocumentFeeder.Enabled = true;
                    // specify that application want to acquire all pages from the feeder
                    device.XferCount = -1;

                    // if pages can be scanned in duplex mode
                    if (device.DocumentFeeder.DuplexMode != Vintasoft.Twain.DuplexMode.None)
                        // enable duplex scanning
                        device.DocumentFeeder.DuplexEnabled = true;

                    // if feeder can detect paper
                    if (device.DocumentFeeder.PaperDetectable)
                    {
                        // if feeder is loaded
                        if (device.DocumentFeeder.Loaded)
                            // acquire images asynchronously
                            device.Acquire();
                    }
                    // if feeder cannot detect paper
                    else
                        // acquire images asynchronously
                        device.Acquire();
                }
            }

This C#/VB.NET code shows how to get information about barcodes recognized on acquired image.

            ''' <summary>
            ''' Synchronously acquires images from TWAIN device and retrieves from TWAIN device information about barcodes recognized on acquired images.
            ''' </summary>
            Public Sub SynchronouslyAcquireImageFromTwainDeviceAndRecognizeBarcodeInAcquiredImages()
                Using deviceManager As New Vintasoft.Twain.DeviceManager()
                    Try
                        ' open the device manager
                        deviceManager.Open()

                        deviceManager.ShowDefaultDeviceSelectionDialog()

                        ' get reference to the default device
                        Dim device As Vintasoft.Twain.Device = deviceManager.DefaultDevice

                        ' specify that device UI must not be used
                        device.ShowUI = False
                        ' specify that device must be closed after scan
                        device.DisableAfterAcquire = True

                        ' open the device
                        device.Open()

                        ' specify that device should recognize barcodes in acquired images
                        device.BarcodeRecognizer.IsEnabled = True

                        ' acquire images from device
                        Dim acquireModalState As Vintasoft.Twain.AcquireModalState = Vintasoft.Twain.AcquireModalState.None
                        Do
                            acquireModalState = device.AcquireModal()

                            Select Case acquireModalState
                                Case Vintasoft.Twain.AcquireModalState.ImageAcquired
                                    ' get information about recognized barcodes
                                    Dim recognizedBarcodes As Vintasoft.Twain.TwainBarcodeInfo() = device.BarcodeRecognizer.GetRecognitionResult()
                                    ' if barcodes are NOT found
                                    If recognizedBarcodes.Length = 0 Then
                                        System.Console.WriteLine("Barcodes are NOT found.")
                                    Else
                                        ' if barcodes are found
                                        System.Console.WriteLine(String.Format("{0} barcodes are found.", recognizedBarcodes.Length))
                                        ' for each recognized barcode
                                        For i As Integer = 0 To recognizedBarcodes.Length - 1
                                            ' output barcode type
                                            System.Console.Write(String.Format("BarcodeType={0} ", recognizedBarcodes(i).Type))
                                            ' output barcode text
                                            System.Console.WriteLine(String.Format("BarcodeText='{0}'", recognizedBarcodes(i).Value))
                                        Next
                                    End If

                                    ' if acquired image is present (Native or Memory transfer mode is used)
                                    If device.AcquiredImage IsNot Nothing Then
                                        ' dispose the acquired image
                                        device.AcquiredImage.Dispose()
                                    End If

                                    Exit Select
                            End Select
                        Loop While acquireModalState <> Vintasoft.Twain.AcquireModalState.None

                        ' close the device
                        device.Close()

                        ' close the device manager
                        deviceManager.Close()
                    Catch ex As Vintasoft.Twain.TwainException
                        System.Console.WriteLine("Error: " + ex.Message)
                        System.Console.ReadLine()
                    End Try
                End Using
            End Sub


            /// <summary>
            /// Synchronously acquires images from TWAIN device and retrieves from TWAIN device information about barcodes recognized on acquired images.
            /// </summary>
            public void SynchronouslyAcquireImageFromTwainDeviceAndRecognizeBarcodeInAcquiredImages()
            {
                using (Vintasoft.Twain.DeviceManager deviceManager = new Vintasoft.Twain.DeviceManager())
                {
                    try
                    {
                        // open the device manager
                        deviceManager.Open();

                        deviceManager.ShowDefaultDeviceSelectionDialog();

                        // get reference to the default device
                        Vintasoft.Twain.Device device = deviceManager.DefaultDevice;

                        // specify that device UI must not be used
                        device.ShowUI = false;
                        // specify that device must be closed after scan
                        device.DisableAfterAcquire = true;

                        // open the device
                        device.Open();

                        // specify that device should recognize barcodes in acquired images
                        device.BarcodeRecognizer.IsEnabled = true;

                        // acquire images from device
                        Vintasoft.Twain.AcquireModalState acquireModalState = Vintasoft.Twain.AcquireModalState.None;
                        do
                        {
                            acquireModalState = device.AcquireModal();

                            switch (acquireModalState)
                            {
                                case Vintasoft.Twain.AcquireModalState.ImageAcquired:
                                    // get information about recognized barcodes
                                    Vintasoft.Twain.TwainBarcodeInfo[] recognizedBarcodes = device.BarcodeRecognizer.GetRecognitionResult();
                                    // if barcodes are NOT found
                                    if (recognizedBarcodes.Length == 0)
                                    {
                                        System.Console.WriteLine("Barcodes are NOT found.");
                                    }
                                    // if barcodes are found
                                    else
                                    {
                                        System.Console.WriteLine(string.Format("{0} barcodes are found.", recognizedBarcodes.Length));
                                        // for each recognized barcode
                                        for (int i = 0; i < recognizedBarcodes.Length; i++)
                                        {
                                            // output barcode type
                                            System.Console.Write(string.Format("BarcodeType={0} ", recognizedBarcodes[i].Type));
                                            // output barcode text
                                            System.Console.WriteLine(string.Format("BarcodeText='{0}'", recognizedBarcodes[i].Value));
                                        }
                                    }

                                    // if acquired image is present (Native or Memory transfer mode is used)
                                    if (device.AcquiredImage != null)
                                        // dispose the acquired image
                                        device.AcquiredImage.Dispose();

                                    break;
                            }
                        }
                        while (acquireModalState != Vintasoft.Twain.AcquireModalState.None);

                        // close the device
                        device.Close();

                        // close the device manager
                        deviceManager.Close();
                    }
                    catch (Vintasoft.Twain.TwainException ex)
                    {
                        System.Console.WriteLine("Error: " + ex.Message);
                        System.Console.ReadLine();
                    }
                }
            }

member.value:
false - the device should NOT recognize barcodes on acquired images;
true - the device should recognize barcodes on acquired images.

Default value is false.

